        radial-gradient(circle at top left, rgba(124, 58, 237, 0.28), transparent 34rem),
        linear-gradient(135deg, #020617 0%, var(--bg) 55%, #111827 100%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
    }

    main {
      width: min(100%, 520px);
    }

